/* eslint-enable prettier/prettier */

const PERIOD_BY_COUNT = { 260: "daily", 52: "weekly", 26: "biweekly", 24: "semimonthly", 12: "monthly", 1: "annual" };
const STATUSES = ["single", "married", "marriedAtSingleRate"];

function validateForm(form) {
  if (form === null || form === undefined) return;
  const fail = (m) => {
    throw new Error(`New York IT-2104: ${m}`);
  };
  if (!STATUSES.includes(form.filingStatus)) fail(`filingStatus must be one of ${STATUSES.join(", ")}`);
  for (const k of ["stateAllowances", "nycAllowances"]) {
    const v = form[k] ?? 0;
    if (!Number.isInteger(v) || v < 0) fail(`${k} must be a non-negative integer`);
  }
  for (const k of ["additionalStateCents", "additionalNycCents", "additionalYonkersCents"]) {
    const v = form[k] ?? 0;
    if (!Number.isSafeInteger(v) || v < 0) fail(`${k} must be a non-negative integer`);
  }
  if (form.nycResident && form.yonkersResident) fail("an employee can't be a resident of both New York City and Yonkers");
  if (!form.nycResident && (form.nycAllowances || form.additionalNycCents)) {
    fail("New York City allowances or additional withholding given for a non-resident");
  }
  if (!form.yonkersResident && form.additionalYonkersCents) fail("Yonkers additional withholding given for a non-resident");
  if (form.worksInYonkers !== undefined && typeof form.worksInYonkers !== "boolean") fail("worksInYonkers must be true or false");
}

/** Yonkers nonresident earnings tax, NYS-50-T-Y Method VIII. */
function yonkersNonresidentCents(y, wagesCents, payPeriodsPerYear) {
  const annual = wagesCents * payPeriodsPerYear;
  if (annual <= y.noTaxUpToCents) return 0;
  let exclusion = 0;
  for (const [over, ex] of y.exclusions) if (annual > over) exclusion = ex;
  return Math.round(((annual - exclusion) * y.rateBp) / 10_000 / payPeriodsPerYear);
}

/** One jurisdiction's Method II (and Method III, if it has one). */
function methodTwo(table, { wagesCents, payPeriodsPerYear, status, allowances }) {
  const period = PERIOD_BY_COUNT[payPeriodsPerYear];
  const allowanceCents = table.deductionCents[period][status] + allowances * table.exemptionCents[period];
  const net = Math.max(0, wagesCents - allowanceCents);

  if (table.method3) {
    const annualized = net * payPeriodsPerYear;
    const top = table.method3[status];
    if (annualized >= top[0][0]) {
      let rate = top[0][1];
      for (const [from, r] of top) if (annualized >= from) rate = r;
      return { cents: Math.round((annualized * rate) / 10_000 / payPeriodsPerYear), net, method: "III" };
    }
  }
  const rows = table.method2[status][period];
  let row = rows[0];
  for (const r of rows) if (net >= r[0]) row = r;
  const [atLeast, rate, plus] = row;
  // Steps 3-5, rounding the product to the cent as the booklet examples do.
  return { cents: Math.round(((net - atLeast) * rate) / 10_000) + plus, net, method: "II" };
}

function compute({ taxYear, wagesCents, payPeriodsPerYear, form, federalW4 = null }) {
  const t = TABLES[taxYear];
  if (!PERIOD_BY_COUNT[payPeriodsPerYear]) {
    throw new Error(
      `New York tables cover daily, weekly, biweekly, semimonthly, monthly and annual pay only (got ${payPeriodsPerYear} periods a year)`
    );
  }
  validateForm(form);

  let f;
  let formBasis;
  if (form) {
    f = form;
    formBasis = "it-2104";
  } else if (federalW4 && federalW4.formYear < 2020) {
    const married = federalW4.maritalStatus === "married";
    f = { filingStatus: married ? "married" : "single", stateAllowances: federalW4.allowances };
    formBasis = "none-on-file-used-pre-2020-w4";
  } else {
    f = { filingStatus: "single", stateAllowances: 0 };
    formBasis = "none-on-file-single-zero";
  }
  const status = f.filingStatus === "married" ? "married" : "single";

  const state = methodTwo(t.NYS, {
    wagesCents,
    payPeriodsPerYear,
    status,
    allowances: f.stateAllowances ?? 0,
  });
  const localities = {};
  if (f.nycResident) {
    const nyc = methodTwo(t.NYC, { wagesCents, payPeriodsPerYear, status, allowances: f.nycAllowances ?? 0 });
    localities.NYC = nyc.cents + (f.additionalNycCents ?? 0);
  }
  if (f.yonkersResident) {
    localities.YONKERS = Math.round(state.cents * t.yonkersSurchargeRate) + (f.additionalYonkersCents ?? 0);
  } else if (f.worksInYonkers) {
    localities.YONKERS_NR = yonkersNonresidentCents(t.yonkersNonresident, wagesCents, payPeriodsPerYear);
  }

  return {
    stateCents: state.cents + (f.additionalStateCents ?? 0),
    localities,
    formBasis,
    lines: { netWagesCents: state.net, method: state.method },
  };
}

module.exports = {
  code: "NY",
  name: "New York",
  wageBasis: "federal-income-tax-wages",
  years: Object.keys(TABLES).map(Number),
  TABLES,
  validateForm,
  compute,
};
